	    public void EncodeBase64NVARCHARFields(ContainerPM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SearchFields)) //T4 find type == nText 
            {
                entityPM.SearchFields = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SearchFields));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.ExceptionResolvedDescription)) //T4 find type == nText 
            {
                entityPM.ExceptionResolvedDescription = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.ExceptionResolvedDescription));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.LastExceptionDescription)) //T4 find type == nText 
            {
                entityPM.LastExceptionDescription = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.LastExceptionDescription));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.ExceptionDescription)) //T4 find type == nText 
            {
                entityPM.ExceptionDescription = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.ExceptionDescription));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
		}
	    public void AddPOCOPropertyName(POCOPropertyNames pocoPropertyName)
        {
